if (get(ctx.subject.employer, 'entity_extension_data.working_time_regime', 'STANDARD') !== 'STANDARD') return false;
const clock = (t) => Number(t.substring(0, 2)) * 60 + Number(t.substring(3, 5));
const planned = (shift) => {
	const v = shift.variant;
	if (get(v, 'untimed_hours', null) != null) return get(v, 'untimed_hours', null);
	if (get(v, 'start_time', null) == null || get(v, 'end_time', null) == null) return 0;
	let total = clock(get(v, 'end_time', null)) - clock(get(v, 'start_time', null)) + (get(v, 'ends_next_day', false) === true ? 1440 : 0);
	for (const b of get(v, 'breaks', [])) if (get(b, 'paid', false) !== true) total = total - ((clock(b.end_time) - clock(b.start_time) + 1440) % 1440);
	return Math.max(0, total / 60);
};
return ctx.reads.roster_entry.some((row) => {
	if (get(row, 'actual_worked_intervals', []).length === 0) return false;
	const shift = ctx.reads.shift_definition.find((item) => item.id === row.shift_definition_id);
	if (shift == null) return false;
	if (get(shift, 'variant.day_type', 'WORK') === 'REST') return false;
	return planned(shift) > ctx.lookup.standard_daily_hours;
});

